import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();
        int m = n * (n - 1) / 2;

        int maxX = n * (n - 1);
        int[][] dp = new int[n + 1][maxX + 1];
        int[][] dp1 = new int[n + 1][maxX + 1];

        dp[1][m] = 1;

        for (int i = 2; i <= n; i++) {
            int startX = m - (i - 1) * (i - 2) / 2;
            int endX = m + (i - 1) * (i - 2) / 2;
            for (int x = startX; x <= endX; x++) {
                for (int d = -i + 1; d < i; d++) {
                    int xIndex = x + d;
                    if (xIndex >= 0 && xIndex <= maxX) {
                        dp[i][xIndex] = (dp[i][xIndex] + (int)((long)dp[i - 1][x] * (i - Math.abs(d)) % mod)) % mod;
                    }
                }
            }
        }

        for (int i = 2; i <= n; i++) {
            int startX = m - (i - 1) * (i - 2) / 2;
            int endX = m + (i - 1) * (i - 2) / 2;
            for (int x = startX; x <= endX; x++) {
                long val = ((long)dp1[i - 1][x] * i) % mod;
                dp1[i][x] = (int) val;
            }
            for (int x = startX; x <= endX; x++) {
                for (int d = 1; d < i; d++) {
                    int xIndex = x - d;
                    if (xIndex >= 0 && xIndex <= maxX) {
                        long addVal = ((long)dp[i - 1][x] * (i - d)) % mod;
                        dp1[i][xIndex] = (int)((dp1[i][xIndex] + addVal) % mod);
                    }
                }
            }
        }

        int result = 0;
        int startX = m + 1;
        int endX = m + (n - 1) * (n - 2) / 2;
        for (int x = startX; x <= endX; x++) {
            result = (result + dp1[n][x]) % mod;
        }
        System.out.println(result);
        sc.close();
    }
}

